import {scenarios,metrics,technologies} from './cloud-model.js';
const action=(id,text,secondary=false)=>`<button class="${secondary?'story-secondary':'story-primary'}" data-cloud="${id}">${text}</button>`;
const number=n=>n.toLocaleString('en-US');
function routeMap(s,elastic,m){const id=elastic?'elastic':'fixed';const stressed=m.queue>0;const broken=s.scenario==='SERVER FAILURE'&&!s.recovered;const n=m.resources;const speed=[2.4,1.7,1.05,.65][s.pressure];const dots=[3,7,12,18][s.pressure];return `<svg class="resource-map ${stressed?'map-stressed':''} ${broken?'map-broken':''}" viewBox="0 0 300 125" aria-hidden="true"><path class="distribution-line" d="M150 0 V12"/>${Array.from({length:6},(_,i)=>{const x=34+(i%3)*116,y=i<3?42:99;const enabled=i<n;const path=`M150 0 C150 ${y-17} ${x} 5 ${x} ${y-13}`;const added=elastic&&((s.pressure===2&&i>=2)||(s.pressure===3&&i>=4));return `<g class="resource-slot ${enabled?'resource-live':'resource-empty'} ${added?'resource-added':''} ${broken&&i===0?'resource-failed':''}">${enabled?`<path id="route-${id}-${i}" class="distribution-line" d="${path}"/>`:''}<rect x="${x-25}" y="${y-12}" width="50" height="26" rx="5"/><path class="resource-slats" d="M${x-17} ${y-4} h24 M${x-17} ${y+3} h24"/><circle class="resource-led" cx="${x+15}" cy="${y}" r="2.4"/>${enabled?`<text x="${x}" y="${y+25}" text-anchor="middle">${broken&&i===0?'OFFLINE':added?'ADDED':'READY'}</text>`:''}</g>`;}).join('')}${!broken?Array.from({length:dots},(_,i)=>{const target=i%n,x=34+(target%3)*116,y=target<3?42:99;return `<circle class="traffic-packet" r="${s.pressure>1?2.5:2}" style="--packet-delay:${i*.13}s"><animateMotion dur="${speed}s" begin="-${(i*speed/dots).toFixed(2)}s" repeatCount="indefinite" path="M150 0 C150 ${y-17} ${x} 5 ${x} ${y-13}"/></circle>`;}).join(''):''}</svg>`;}
function systems(s,m){const degraded=m.queue>0;const failed=s.scenario==='SERVER FAILURE'&&!s.recovered;return `<div class="workload-nodes ${degraded?'degraded':''} ${failed?'nodes-failed':''}"><div class="customer-system"><span>▦</span><b>APPLICATION</b><i>${failed?'OFFLINE':degraded?'SLOW':'ONLINE'}</i></div><div class="customer-system"><span>◈</span><b>WEBSITE</b><i>${failed?'OFFLINE':degraded?'WAITING':'ONLINE'}</i></div></div><div class="workload-context"><span>ERP</span><span>CRM</span><span>DATABASE ${s.scenario==='DATA GROWTH'?'▰▰▰▰▱':''}</span>${s.scenario==='NEW APPLICATION'?'<span class="new-app-chip">＋ NEW APP</span>':''}</div>`;}
function panel(s,elastic=false){const m=metrics(s,elastic);const risk=m.queue>0;return `<article class="capacity-panel ${elastic?'elastic-panel':'fixed-panel'} ${risk?'under-pressure':''} ${s.scenario==='DATA GROWTH'?'data-growing':''}"><div class="capacity-heading"><span>${s.comparison?(elastic?'AFTER':'BEFORE'):'CURRENT ENVIRONMENT'}</span><strong>${elastic?'ELASTIC CAPACITY':'FIXED CAPACITY'}</strong></div>${systems(s,m)}${routeMap(s,elastic,m)}<div class="resource-count"><b data-count="${m.resources}" data-count-key="${elastic?'after':'before'}-resources">${m.resources}</b><span>resources${elastic&&s.resources>2?' · capacity added':''}</span><i>${risk?'AT LIMIT':elastic&&s.resources>2?'RESPONDING':'HEALTHY'}</i></div><div class="capacity-pressure"><span>PRESSURE</span><div><i data-meter="${m.cpu}" data-meter-key="${elastic?'after':'before'}-pressure" style="width:${m.cpu}%"></i></div><b data-count="${m.cpu}" data-count-key="${elastic?'after':'before'}-cpu" data-suffix="%">${m.cpu}%</b></div><div class="queue-visual ${risk?'queue-active':''}" aria-label="${m.queue?number(m.queue)+' simulated queued requests per minute':'No queue in this model'}"><div>${Array.from({length:Math.min(10,Math.ceil(m.queue/750))},()=>'<i></i>').join('')}</div><span>${m.queue?'Requests waiting':elastic&&s.pressure===3?'Traffic redistributed':'Requests flowing'}</span></div>${s.comparison?`<p class="panel-outcome">${risk?'Capacity is constrained. Requests begin to wait.':elastic&&s.pressure>1?'More capacity. Work keeps moving.':'Ready for the same demand.'}</p>`:''}</article>`;}
function businessConsequences(s){if(s.scenario==='SERVER FAILURE')return s.recovered?['Recovery path demonstrated','Validate the restored service']:['Critical service unavailable','Operational intervention required'];if(s.scenario==='DATA GROWTH')return ['Storage headroom is shrinking','Data operations may be constrained'];if(s.scenario==='NEW APPLICATION')return ['New dependencies to support','Capacity planning required'];if(s.scenario==='BACKUP & RECOVERY')return s.recovered?['Recovery copy is usable in this model','Validate data integrity and readiness']:['Backup exists; recovery is unproven','A restore rehearsal is needed'];if(s.pressure>=2)return s.comparison?['Fixed: customer experience at risk','Elastic: added capacity supports demand']:['Customer experience at risk','Transactions may queue','Application responsiveness affected','Operational intervention may be required'];return ['Applications serving the business','Capacity matches current demand'];}
function storyText(s){switch(s.moment){
 case 'normal':return ['NORMAL','The business is moving.','Customers use applications. Infrastructure handles the demand.'];
 case 'trigger':return ['TRIGGER',s.pressure===0?'What if demand suddenly rises?':s.pressure===1?'More customers arrive.':'The queue starts to grow.','Watch demand rise while the available capacity stays fixed.'];
 case 'consequence':return ['CONSEQUENCE','More demand. The same capacity.','The website slows, requests wait, and the team may need to intervene.'];
 case 'question':return ['QUESTION',"Demand changed.<br>Your infrastructure didn't.",'What would a different response to demand make possible?'];
 case 'compare':return ['TRANSFORM','Same workload. A different response.','Both start with the same demand. The right side is configured to add capacity in this conceptual model.'];
 case 'retest':return ['SAME TEST AGAIN',s.pressure<2?'The same demand is arriving.':'Capacity joins the workload.','Fixed capacity stays the same. Additional resources take a share of the incoming traffic.'];
 case 'stabilized':return ['RESPONSE','Demand peaks. Capacity responds.','The fixed environment queues requests. The elastic design distributes work across added resources.'];
 case 'takeaway':case 'capabilities':return ['REVEAL',"The workload didn't change.<br>The way infrastructure responds did.",'This is why the architecture matters to the customer experience.'];
 default:{const labels={
 'SERVER FAILURE':s.recovered?['Recovery demonstrated.','Service resumes through the modeled recovery path. Real recovery must be designed and tested.']:['One server stops. Work is interrupted.','A critical dependency is unavailable. This model has no automatic failover.'],
 'DATA GROWTH':['Data grows. Room to operate shrinks.','Storage reaches 92% in this model. Retention and expansion now need attention.'],
 'NEW APPLICATION':['One more application. More to support.','A new system joins the same infrastructure and introduces additional dependencies.'],
 'BACKUP & RECOVERY':s.recovered?['A backup becomes a recovery path.','The copy is restored into an isolated target. Validation is part of recovery.']:['A backup is only the beginning.','Restore the copy to see the difference between having data and recovering a service.']};const l=labels[s.scenario]||['Change a condition. See the consequence.',''];return ['CAUSE → RESPONSE',l[0],l[1]];}
}}
function storyControls(s){switch(s.moment){
 case 'normal':return action('scenario','TRIGGER TRAFFIC SPIKE →').replace('data-cloud="scenario"','data-cloud="scenario" data-value="TRAFFIC SPIKE"');
 case 'trigger':case 'retest':return s.running?action('pause','Pause escalation',true):action('resume','Resume escalation →');
 case 'consequence':return action('question','WHAT CHANGED? →');
 case 'question':return action('transform','WHAT WOULD CLOUD CHANGE? →');
 case 'compare':return action('retest','RUN THE SAME TRAFFIC SPIKE →');
 case 'stabilized':return action('takeaway','REVEAL WHAT CHANGED →');
 case 'takeaway':return action('reveal','EXPLORE HOW →');
 case 'capabilities':return action('retest','Run the comparison again',true);
 default:return ['SERVER FAILURE','BACKUP & RECOVERY'].includes(s.scenario)&&!s.recovered?action('recover','SIMULATE RECOVERY →'):action('clear','Return to normal →',true);
}}
export function cloudStory(s){const m=metrics(s);const text=storyText(s);const consequences=businessConsequences(s);return `<section class="business-stage ${s.comparison?'comparison-stage':''} moment-${s.moment} pressure-${s.pressure}" aria-label="Cloud business story"><div class="story-toolbar"><span>${s.environment}</span><span class="sim-label">SIMULATED DATA</span><button class="text-button" data-cloud="prev">← Previous</button></div><div class="story-scenarios"><label for="scenario-picker">SCENARIO</label><select id="scenario-picker" data-cloud-select="scenario"><option value="" ${!s.scenario?'selected':''} disabled>Choose a condition</option>${scenarios.map(x=>`<option ${s.scenario===x?'selected':''}>${x}</option>`).join('')}</select>${s.scenario?action('clear','Normal state',true):''}</div><div class="demand-rail"><div><span class="demand-caption">${s.comparison?'SAME DEMAND · BOTH ENVIRONMENTS':'BUSINESS DEMAND'}</span><strong data-count="${m.demand}" data-count-key="demand">${number(m.demand)}</strong><small>requests/min</small></div><div class="demand-particles" style="--stream-duration:${[2.6,1.8,1,.6][s.pressure]}s" aria-hidden="true">${Array.from({length:[3,6,10,15][s.pressure]},(_,i)=>`<i style="--particle-start:${-(i*.23)}s;--particle-y:${15+(i%3)*14}%"></i>`).join('')}</div><span class="demand-stage">${s.pressure===0?'NORMAL':s.pressure===3?'PEAK':'RISING'}</span></div><div class="story-systems">${panel(s)}${s.comparison?panel(s,true):''}</div>${s.scenario==='BACKUP & RECOVERY'||s.recovered?`<div class="story-recovery"><span>▣ BACKUP COPY</span><i>→</i><span>${s.recovered?'RESTORE DEMONSTRATED ✓':'ISOLATED RECOVERY TARGET'}</span></div>`:''}<div class="business-effects ${s.pressure>=2&&!s.comparison?'effects-risk':''}" aria-label="Business consequence">${consequences.map(t=>`<span>${t}</span>`).join('')}</div><div class="story-consequence" aria-live="polite"><div><span class="story-moment">${text[0]}</span><h2>${text[1]}</h2><p>${text[2]}</p></div><div class="story-cta">${storyControls(s)}</div></div><div class="story-foot"><button class="text-button" data-cloud="details" aria-expanded="${s.details}">${s.details?'Hide':'Show'} secondary metrics ${s.details?'−':'＋'}</button><span>Conceptual response, not a scaling guarantee.</span></div>${s.details?`<div class="story-metrics"><span>SIMULATED DATA</span><p>Fixed queue: <b>${number(metrics(s,false).queue)}</b> requests/min · ${s.comparison?`Elastic queue: <b>${number(m.queue)}</b> requests/min · `:''}Storage: <b>${m.storage}%</b></p><p>Resources represent illustrative capacity units. Actual behavior depends on architecture, scaling policy, quotas, dependencies and startup time.</p></div>`:''}</section>${s.reveal&&s.moment==='capabilities'?capabilityLayer():''}<div class="story-understage"><p>${s.environment==='OTHER CLOUD'?'Other Cloud can already use elastic capacity. The fixed starting point here is a selected architecture/configuration—not a limitation of the cloud provider.':s.environment==='HYBRID'?'A hybrid environment can also scale. Here, the selected workload begins with fixed capacity.':'The selected workload begins with fixed capacity. Cloud still needs an appropriate design and scaling policy.'}</p><button class="secondary" data-cloud="${s.migration?'close-migration':'migrate'}">${s.migration?'Close migration rehearsal':'Explore workload migration'} ${s.migration?'−':'＋'}</button></div>`;}
function capabilityLayer(){return `<section class="tech-reveal story-capabilities"><div class="eyebrow">THE TECHNOLOGY BEHIND THE RESPONSE</div><h2>Now the building blocks have a purpose.</h2><p>A conceptual architecture. The right combination depends on the workload.</p><div>${['Compute','Load Balancing','Networking','Monitoring','Storage','Security','Containers','Serverless'].map(name=>{const description=technologies.find(x=>x[0]===name)[1];return `<article><h3>${name}</h3><p>${description}${['Containers','Serverless'].includes(name)?' Where appropriate for the application.':''}</p></article>`;}).join('')}</div><aside>Where would a change in demand put your customer experience under pressure?</aside></section>`;}
